function getClaudeTranslation(key, lang) {
  if (claudeTranslations[lang] && claudeTranslations[lang][key]) {
    return claudeTranslations[lang][key];
  }
  if (claudeTranslations.en && claudeTranslations.en[key]) {
    return claudeTranslations.en[key];
  }
  return null;
}

function applyClaudeTranslations(lang) {
  console.log(`🔥 Applying claude translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.claude.') || key.startsWith('review.common.'))) {
      const translation = getClaudeTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} claude translations`);
}

window.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyClaudeTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyClaudeTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyClaudeTranslations(currentLang);
}

console.log('✅ claude i18n loaded');
